-- 061_seed_crops_agronomy_from_prod.sql
--
-- Фиксация агрономии культур, которая жила ТОЛЬКО в проде.
--
-- Обнаружено 2026-07-30 при подключении культуро-специфичных советов дня
-- (`getCropStageTip`, см. session-note): на проде `watering_details.notes` заполнен
-- у 54 культур из 55, а в миграциях репозитория — лишь у ~30 (006 — овощи/зелень/ягоды,
-- 038 — кусты и деревья; 033 дополнял только `fertilizing_schedule`). Разницу примерно
-- в 24 культуры когда-то вносили прямо в прод, мимо git.
--
-- Чем это грозило: БД, поднятая с нуля по миграциям (локальная разработка, стенд,
-- восстановление после потери), получала бедный справочник, и советы дня молча
-- откатывались на общий пул по стадии — то есть регресс, который никак себя не проявляет,
-- кроме менее полезных советов.
--
-- Содержимое ниже — дамп прод-значений `watering_details` / `fertilizing_schedule` /
-- `diseases` / `pests` по всем 54 культурам, у которых есть хоть одно из этих полей.
-- Перезаписывает данные из 006/033/038 их же текущими прод-значениями, поэтому
-- повторный прогон безопасен и порядок миграций не важен. Идемпотентно.
--
-- Единственная культура без агрономии — Петуния — дописана вручную в конце файла.

UPDATE crops SET watering_details = '{"notes": "В период созревания плодов полив резко сокращают — улучшает сахаристость.", "growing": {"freq_days": 5, "amount_l_m2": 6}, "fruiting": {"freq_days": 7, "amount_l_m2": 4}}'::jsonb, fertilizing_schedule = '[{"dose": "10 г на 10 л", "notes": "", "stage": "growing", "method": "root", "timing": "Через 2 недели после высадки", "fertilizer_type": "N", "product_example": "Мочевина (азот, карбамид)"}, {"dose": "15 г на 10 л", "notes": "", "stage": "flowering", "method": "root", "timing": "В начале цветения", "fertilizer_type": "PK", "product_example": "Монофосфат калия (фосфор + калий)"}, {"dose": "20 г на 10 л", "notes": "Сахаристость", "stage": "fruiting", "method": "root", "timing": "Плоды размером с кулак", "fertilizer_type": "K", "product_example": "Сульфат калия (калий)"}]'::jsonb, diseases = '[{"name": "Антракноз", "symptoms": "Оливковые пятна на листьях, вдавленные на плодах", "treatment": "Бордоская смесь", "conditions": "Влажность", "prevention": "Севооборот"}]'::jsonb, pests = '[{"name": "Паутинный клещ", "signs": "Паутина, обесцвечивание листьев", "treatment": "Фитоверм", "prevention": "Поддержание влажности воздуха"}, {"name": "Бахчевая тля", "signs": "Колонии под листьями", "treatment": "Актара", "prevention": ""}]'::jsonb WHERE name = 'Арбуз';
UPDATE crops SET watering_details = '{"notes": "Регулярный умеренный полив. Не любит холодную воду и переувлажнение.", "growing": {"freq_days": 2, "amount_l_m2": 3}}'::jsonb, fertilizing_schedule = '[{"dose": "5 г на 10 л", "notes": "Слабая подкормка", "stage": "growing", "method": "root", "timing": "Через 3 недели после высадки", "fertilizer_type": "N", "product_example": "Мочевина (азот, карбамид)"}]'::jsonb, diseases = '[{"name": "Фузариоз", "symptoms": "Потемнение стебля, увядание", "treatment": "Превикур", "conditions": "Заражённая почва", "prevention": "Здоровый грунт, дренаж"}]'::jsonb, pests = '[{"name": "Тля", "signs": "Колонии на молодых листьях", "treatment": "Мыльный раствор", "prevention": ""}]'::jsonb WHERE name = 'Базилик';
UPDATE crops SET watering_details = '{"notes": "Самая теплолюбивая культура. Полив только тёплой водой. При температуре ниже 15°C рост прекращается.", "growing": {"freq_days": 3, "amount_l_m2": 5}, "fruiting": {"freq_days": 2, "amount_l_m2": 8}, "seedling": {"freq_days": 4, "amount_l_m2": 2}, "flowering": {"freq_days": 2, "amount_l_m2": 7}}'::jsonb, fertilizing_schedule = '[{"dose": "20 г на 10 л", "notes": "", "stage": "growing", "method": "root", "timing": "Через 2 недели после высадки", "fertilizer_type": "NPK", "product_example": "Кемира (комплекс NPK)"}, {"dose": "15 г на 10 л", "notes": "Снизить долю азота", "stage": "flowering", "method": "root", "timing": "В начале цветения", "fertilizer_type": "PK", "product_example": "Монофосфат калия (фосфор + калий)"}, {"dose": "20 г на 10 л", "notes": "", "stage": "fruiting", "method": "root", "timing": "Каждые 2 недели", "fertilizer_type": "K", "product_example": "Сульфат калия (калий)"}]'::jsonb, diseases = '[{"name": "Фомопсис (сухая гниль)", "symptoms": "Светлые пятна с тёмным ободком на листьях, затем стебель и плоды", "treatment": "ХОМ, Скор", "conditions": "Высокая влажность и температура", "prevention": "Севооборот, обеззараживание семян"}, {"name": "Вертициллёзное увядание", "symptoms": "Пожелтение и увядание снизу вверх", "treatment": "Профилактика Превикуром", "conditions": "Заражённая почва", "prevention": "Севооборот минимум 4 года, устойчивые сорта"}]'::jsonb, pests = '[{"name": "Колорадский жук", "signs": "Яйца и личинки на листьях, полное объедание", "treatment": "Актара, Командор, ручной сбор", "prevention": "Мульчирование соломой"}, {"name": "Паутинный клещ", "signs": "Паутина, обесцвечивание листьев", "treatment": "Фитоверм, Акарин", "prevention": "Опрыскивание листьев водой"}]'::jsonb WHERE name = 'Баклажан';
UPDATE crops SET watering_details = '{"notes": "Умеренный полив. Засухоустойчивы. Переувлажнение вызывает загнивание.", "growing": {"freq_days": 3, "amount_l_m2": 3}}'::jsonb, fertilizing_schedule = '[{"dose": "10 г на 10 л", "notes": "", "stage": "growing", "method": "root", "timing": "Через 2 недели после высадки", "fertilizer_type": "NPK", "product_example": "Нитрофоска (NPK)"}]'::jsonb, diseases = '[{"name": "Серая гниль", "symptoms": "Серый налёт на цветах в дождливую погоду", "treatment": "Фундазол", "conditions": "Высокая влажность", "prevention": "Дренаж, не загущать"}]'::jsonb, pests = '[{"name": "Тля", "signs": "Колонии на побегах", "treatment": "Мыльный раствор", "prevention": "Привлечение хищников"}]'::jsonb WHERE name = 'Бархатцы';
UPDATE crops SET watering_details = '{"notes": "3–4 полива за сезон (30–40 л под дерево). Важен: через 2 недели после цветения и после сбора ягод для восстановления дерева. В период созревания НЕ поливать — трескаются ягоды.", "growing": {"freq_days": 21, "amount_l_m2": 25}, "fruiting": {"freq_days": 14, "amount_l_m2": 30}}'::jsonb, fertilizing_schedule = '[{"dose": "20 г на 1 м² приствольного круга", "notes": "", "stage": "growing", "method": "root", "timing": "Ранняя весна", "fertilizer_type": "N", "product_example": "Аммиачная селитра"}, {"dose": "30 г под дерево", "notes": "", "stage": "flowering", "method": "root", "timing": "Через 2 недели после цветения", "fertilizer_type": "NPK", "product_example": "Нитрофоска"}, {"dose": "По 20 г на 1 м²", "notes": "Закладка плодовых почек", "stage": "done", "method": "root", "timing": "После сбора урожая (июль)", "fertilizer_type": "PK", "product_example": "Суперфосфат + сульфат калия"}, {"dose": "0,5 кг под дерево + раскисление при необходимости", "notes": "", "stage": "done", "method": "root", "timing": "Октябрь", "fertilizer_type": "PK", "product_example": "Зола"}]'::jsonb, diseases = '[{"name": "Коккомикоз", "symptoms": "Красно-бурые пятна на листьях с розовым налётом снизу, массовый преждевременный листопад в июле", "treatment": "Хорус, Скор до и после цветения и после сбора урожая", "conditions": "Влажное лето, загущённые посадки", "prevention": "Уборка опавших листьев, устойчивые сорта (Молодёжная, Шоколадница)"}, {"name": "Монилиоз (монилиальный ожог)", "symptoms": "Засыхание цветков, молодых побегов и листьев («как ожог») весной; бурые мумифицированные ягоды", "treatment": "Хорус до и в период цветения, Свитч — позже", "conditions": "Влажная прохладная погода в период цветения", "prevention": "Удаление и сжигание засохших ветвей, не допускать механических повреждений"}, {"name": "Клястероспориоз (дырчатая пятнистость)", "symptoms": "Бурые пятна на листьях, которые выпадают — остаются сквозные отверстия; язвы и камедетечение на ветках", "treatment": "Хорус, бордоская смесь при листопаде и перед цветением", "conditions": "Влажность, загущение, механические повреждения", "prevention": "Санитарная обрезка, замазывание срезов садовым варом"}]'::jsonb, pests = '[{"name": "Вишнёвая муха", "signs": "Червивые ягоды: личинки внутри, ягода мягкая и темнеет преждевременно", "treatment": "Каратэ, Фуфанон, Искра при появлении мух (май-июнь, через 10 дней после цветения шиповника)", "prevention": "Уборка падалицы; желтые клеевые ловушки"}, {"name": "Вишнёвый слизистый пилильщик", "signs": "Листья объедены до жилок, на них — чёрные слизистые личинки", "treatment": "Инта-Вир, Кинмикс при обнаружении", "prevention": "Осенняя перекопка приствольных кругов"}, {"name": "Тля черёмухово-злаковая", "signs": "Скрученные листья на верхушках побегов, колонии тли", "treatment": "Фитоверм, Биотлин при обнаружении", "prevention": "Уничтожение черёмухи рядом с садом"}]'::jsonb WHERE name = 'Вишня';
UPDATE crops SET watering_details = '{"notes": "Регулярный полив особенно важен в цветении и образовании бобов.", "growing": {"freq_days": 4, "amount_l_m2": 6}, "flowering": {"freq_days": 3, "amount_l_m2": 8}}'::jsonb, fertilizing_schedule = '[{"dose": "10 г на 10 л", "notes": "Азот не нужен — горох фиксирует сам", "stage": "growing", "method": "root", "timing": "В фазе 5-6 листьев", "fertilizer_type": "PK", "product_example": "Суперфосфат (фосфор)"}]'::jsonb, diseases = '[{"name": "Мучнистая роса", "symptoms": "Белый налёт на листьях и бобах", "treatment": "Коллоидная сера, Топаз", "conditions": "Жара + сухость", "prevention": "Ранний посев, устойчивые сорта"}, {"name": "Аскохитоз", "symptoms": "Бурые пятна с чёрными точками на листьях и бобах", "treatment": "ХОМ", "conditions": "Влажность", "prevention": "Севооборот"}]'::jsonb, pests = '[{"name": "Гороховая тля", "signs": "Колонии на молодых побегах", "treatment": "Актеллик, мыльный раствор", "prevention": ""}, {"name": "Гороховая плодожорка", "signs": "Личинки в горошинах", "treatment": "Актеллик до цветения", "prevention": "Ранний посев"}]'::jsonb WHERE name = 'Горох';
UPDATE crops SET watering_details = '{"notes": "3–4 обильных полива за сезон (50–60 л под дерево). Главные: до цветения, после цветения, в период налива. После созревания прекратить — повышает лёжкость.", "growing": {"freq_days": 21, "amount_l_m2": 30}, "fruiting": {"freq_days": 14, "amount_l_m2": 40}}'::jsonb, fertilizing_schedule = '[{"dose": "30 г на 1 м² приствольного круга", "notes": "", "stage": "growing", "method": "root", "timing": "Ранняя весна при распускании почек", "fertilizer_type": "N", "product_example": "Карбамид"}, {"dose": "50 г под дерево", "notes": "", "stage": "flowering", "method": "root", "timing": "Через 3 недели после цветения", "fertilizer_type": "NPK", "product_example": "Нитроаммофоска"}, {"dose": "40 г + 0,5 кг/м²", "notes": "", "stage": "done", "method": "root", "timing": "Сентябрь — после листопада", "fertilizer_type": "PK", "product_example": "Суперфосфат + зола"}]'::jsonb, diseases = '[{"name": "Парша груши", "symptoms": "Оливковые пятна на листьях, растрескивание и уродство плодов", "treatment": "Хорус, Скор, Раёк до и после цветения", "conditions": "Влажная прохладная весна, загущённые кроны", "prevention": "Устойчивые сорта (Чижовская, Лада), сбор листвы"}, {"name": "Монилиоз (плодовая гниль)", "symptoms": "Плоды буреют и гниют прямо на ветке; на поверхности — кольца серых подушечек спор", "treatment": "Хорус, Свитч при первых признаках", "conditions": "Влажное лето, поражения вредителями", "prevention": "Удалять гнилые плоды, не оставлять мумии на ветках"}, {"name": "Ржавчина", "symptoms": "Ярко-оранжевые выпуклые пятна на листьях, на нижней стороне — коричневые выросты", "treatment": "Скор, Байлетон при первых признаках", "conditions": "Наличие можжевельника (промежуточного хозяина) рядом", "prevention": "Не сажать можжевельник казацкий рядом с грушей"}]'::jsonb, pests = '[{"name": "Грушевая медяница", "signs": "Сладкие липкие выделения («медвяная роса»), почернение листьев от сажистого гриба", "treatment": "Актара, Искра при набухании почек", "prevention": "Побелка штамба, уничтожение растительных остатков"}, {"name": "Плодожорка грушевая", "signs": "Червивые плоды с ходами, падалица", "treatment": "Кинмикс, Искра через 2 недели после цветения; повтор через 14 дней", "prevention": "Ловчие пояса на стволах, уборка падалицы"}, {"name": "Тля", "signs": "Скрученные листья на кончиках побегов, колонии зеленоватых насекомых", "treatment": "Фитоверм, Биотлин при обнаружении", "prevention": "Бархатцы и укроп рядом"}]'::jsonb WHERE name = 'Груша';
UPDATE crops SET watering_details = '{"notes": "Перед созреванием полив сокращать — трескается при избытке влаги.", "growing": {"freq_days": 5, "amount_l_m2": 6}, "fruiting": {"freq_days": 8, "amount_l_m2": 4}}'::jsonb, fertilizing_schedule = '[{"dose": "15 г на 10 л", "notes": "", "stage": "growing", "method": "root", "timing": "Через 2 недели после высадки", "fertilizer_type": "NPK", "product_example": "Нитроаммофоска (NPK)"}, {"dose": "20 г на 10 л", "notes": "", "stage": "fruiting", "method": "root", "timing": "При завязывании плодов", "fertilizer_type": "K", "product_example": "Сульфат калия (калий)"}]'::jsonb, diseases = '[{"name": "Мучнистая роса", "symptoms": "Белый налёт на листьях", "treatment": "Коллоидная сера", "conditions": "Жара + влажность", "prevention": "Проветривание теплицы"}]'::jsonb, pests = '[{"name": "Бахчевая тля", "signs": "Колонии под листьями", "treatment": "Актара", "prevention": ""}, {"name": "Паутинный клещ", "signs": "Паутина", "treatment": "Фитоверм", "prevention": ""}]'::jsonb WHERE name = 'Дыня';
UPDATE crops SET watering_details = '{"notes": "Регулярный полив в период налива ягод (июль-август). Мульчирование торфом обязательно — корни поверхностные.", "growing": {"freq_days": 7, "amount_l_m2": 8}, "fruiting": {"freq_days": 5, "amount_l_m2": 10}}'::jsonb, fertilizing_schedule = '[{"dose": "20 г на 1 м²", "notes": "Стимулирует прирост побегов замещения", "stage": "growing", "method": "root", "timing": "Ранней весной", "fertilizer_type": "N", "product_example": "Аммиачная селитра"}, {"dose": "15 г на 10 л", "notes": "", "stage": "flowering", "method": "root", "timing": "В период цветения", "fertilizer_type": "PK", "product_example": "Монофосфат калия"}, {"dose": "По 20 г на 1 м²", "notes": "Закладка почек следующего года", "stage": "fruiting", "method": "root", "timing": "После сбора урожая", "fertilizer_type": "PK", "product_example": "Суперфосфат + сульфат калия"}]'::jsonb, diseases = '[{"name": "Серая гниль", "symptoms": "Серый налёт на ягодах в дождливый период", "treatment": "Свитч, Тиовит Джет до и после цветения", "conditions": "Высокая влажность, загущение", "prevention": "Мульча под кустами, хорошая проветриваемость"}, {"name": "Ржавчина", "symptoms": "Оранжевые споровые подушечки на нижней стороне листьев", "treatment": "Бордоская смесь, Топаз", "conditions": "Соседство промежуточных хозяев (осот, мята)", "prevention": "Уничтожение сорняков рядом"}]'::jsonb, pests = '[{"name": "Малинный жук", "signs": "Личинки в ягодах при сборе урожая", "treatment": "Актеллик, Карбофос до цветения", "prevention": "Рыхление почвы под кустами осенью"}, {"name": "Тля", "signs": "Колонии на молодых побегах, скручивание листьев", "treatment": "Фитоверм, мыльный раствор", "prevention": "Бархатцы рядом"}]'::jsonb WHERE name = 'Ежевика';
UPDATE crops SET watering_details = '{"notes": "Полив равномерный, у основания куста. Жимолость чувствительна к застою воды. Мульчирование снижает стресс от засухи.", "growing": {"freq_days": 7, "amount_l_m2": 6}, "fruiting": {"freq_days": 5, "amount_l_m2": 8}}'::jsonb, fertilizing_schedule = '[{"dose": "15 г на 1 м²", "notes": "", "stage": "growing", "method": "root", "timing": "Ранней весной при отрастании побегов", "fertilizer_type": "N", "product_example": "Аммиачная селитра"}, {"dose": "По 20 г и 0,3 кг на куст", "notes": "Закладка почек на следующий год", "stage": "fruiting", "method": "root", "timing": "После сбора ягод (июнь)", "fertilizer_type": "PK", "product_example": "Суперфосфат + зола"}]'::jsonb, diseases = '[{"name": "Мучнистая роса", "symptoms": "Белый налёт на листьях в жаркую погоду", "treatment": "Топаз, коллоидная сера", "conditions": "Сухость + жара", "prevention": "Хорошая продуваемость куста"}, {"name": "Туберкуляриоз", "symptoms": "Красные бугорки на засыхающих ветках", "treatment": "Вырезать больные ветки, обработать медным купоросом", "conditions": "Стресс растения, механические повреждения", "prevention": "Не травмировать кору при уходе"}]'::jsonb, pests = '[{"name": "Тля жимолостная", "signs": "Колонии на молодых побегах в мае, листья скручиваются и желтеют", "treatment": "Фитоверм, Актеллик до цветения", "prevention": "Привлечение полезных насекомых (укроп, петрушка в цвету)"}, {"name": "Листовёртка", "signs": "Листья свёрнуты в трубочки, внутри гусеница", "treatment": "Лепидоцид, Актеллик при обнаружении", "prevention": "Обрезка повреждённых побегов"}]'::jsonb WHERE name = 'Жимолость съедобная';
UPDATE crops SET watering_details = '{"notes": "Поливать под корень, не попадая на листья и цветы. Обильный полив. Мульчирование обязательно. При жаре — ежедневно.", "growing": {"freq_days": 4, "amount_l_m2": 8}, "fruiting": {"freq_days": 3, "amount_l_m2": 12}, "flowering": {"freq_days": 3, "amount_l_m2": 10}}'::jsonb, fertilizing_schedule = '[{"dose": "15 г на 10 л", "notes": "Стимуляция роста листьев", "stage": "growing", "method": "root", "timing": "Через 2 недели после высадки", "fertilizer_type": "N", "product_example": "Мочевина (азот, карбамид)"}, {"dose": "20 г на 10 л", "notes": "Поддержка опыления и завязи", "stage": "flowering", "method": "root", "timing": "При начале цветения", "fertilizer_type": "NPK", "product_example": "Нитрофоска (NPK)"}, {"dose": "1 стакан на 10 л воды", "notes": "Народное средство — эффективно", "stage": "fruiting", "method": "root", "timing": "Каждые 2 недели", "fertilizer_type": "K", "product_example": "Зола (настой)"}]'::jsonb, diseases = '[{"name": "Мучнистая роса", "symptoms": "Белый налёт на листьях, листья желтеют и усыхают", "treatment": "Коллоидная сера, Топаз, раствор соды", "conditions": "Сухой жаркий период, потом влага", "prevention": "Проветривание, не переувлажнять листья"}, {"name": "Серая гниль", "symptoms": "Серый налёт на плодах и стеблях", "treatment": "Фундазол, Свитч", "conditions": "Влажность, механические повреждения", "prevention": "Удалять завядшие цветки с плодов"}]'::jsonb, pests = '[{"name": "Бахчевая тля", "signs": "Колонии на нижней стороне листьев, скручивание", "treatment": "Актара, мыльный раствор, настой золы", "prevention": "Бархатцы, укроп рядом"}, {"name": "Слизни", "signs": "Объеденные листья, серебристые следы", "treatment": "Метальдегид (Гроза), зола вокруг растений", "prevention": "Рыхление почвы, сухая мульча"}]'::jsonb WHERE name = 'Кабачок';
UPDATE crops SET watering_details = '{"notes": "Влаголюбивая культура. В жару поливать ежедневно. В период формирования кочана — особенно обильно. За 2 недели до уборки полив прекратить.", "growing": {"freq_days": 3, "amount_l_m2": 8}, "fruiting": {"freq_days": 2, "amount_l_m2": 12}, "seedling": {"freq_days": 3, "amount_l_m2": 3}}'::jsonb, fertilizing_schedule = '[{"dose": "10 г на 10 л", "notes": "", "stage": "seedling", "method": "root", "timing": "В фазе 3-4 листьев", "fertilizer_type": "N", "product_example": "Аммиачная селитра (азот)"}, {"dose": "10 г на 10 л", "notes": "Активный рост листьев", "stage": "growing", "method": "root", "timing": "Через 2 недели после высадки", "fertilizer_type": "N", "product_example": "Мочевина (азот, карбамид)"}, {"dose": "20 г на 10 л", "notes": "Азот снижать", "stage": "fruiting", "method": "root", "timing": "При завязывании кочана", "fertilizer_type": "PK", "product_example": "Нитрофоска (NPK)"}]'::jsonb, diseases = '[{"name": "Кила", "symptoms": "Вздутия на корнях, растение отстаёт в росте, увядает", "treatment": "Нет лечения; убрать и уничтожить растение", "conditions": "Кислая почва, заражение", "prevention": "Известкование почвы до pH 7, севооборот 5-7 лет"}, {"name": "Чёрная ножка", "symptoms": "Потемнение и перетяжка стебля у основания у рассады", "treatment": "Фитолавин, Превикур", "conditions": "Переувлажнение, загущённость", "prevention": "Прореживание рассады, умеренный полив"}, {"name": "Пероноспороз", "symptoms": "Жёлтые пятна на листьях, серый налёт снизу", "treatment": "Ридомил Голд, ХОМ", "conditions": "Влажность, прохлада", "prevention": "Проветривание, севооборот"}]'::jsonb, pests = '[{"name": "Капустная белянка", "signs": "Жёлтые яйца на листьях, зелёные гусеницы объедают листья", "treatment": "Лепидоцид, Битоксибациллин, Децис", "prevention": "Накрывать нетканым материалом, бархатцы рядом"}, {"name": "Крестоцветная блошка", "signs": "Мелкие дырочки на листьях молодых растений", "treatment": "Актеллик, Карбофос; опыление золой", "prevention": "Ранняя высадка, опыление золой и табаком"}, {"name": "Капустная тля", "signs": "Колонии сизо-зелёной тли на листьях, деформация", "treatment": "Актеллик, Биотлин", "prevention": "Посадки укропа и петрушки рядом"}, {"name": "Слизни", "signs": "Объеденные листья с ходами, ночной вред", "treatment": "Метальдегид, зола, песок вокруг", "prevention": "Рыхление почвы, устранение укрытий"}]'::jsonb WHERE name = 'Капуста белокочанная';
UPDATE crops SET watering_details = '{"notes": "Хорошо переносит заморозки до -5°C. Оптимальная температура 16-20°C.", "growing": {"freq_days": 3, "amount_l_m2": 8}, "fruiting": {"freq_days": 2, "amount_l_m2": 10}}'::jsonb, fertilizing_schedule = '[{"dose": "15 г на 10 л", "notes": "", "stage": "growing", "method": "root", "timing": "Через 2 недели после высадки", "fertilizer_type": "N", "product_example": "Аммиачная селитра (азот)"}, {"dose": "20 г на 10 л", "notes": "+ бор (2 г/10 л)", "stage": "fruiting", "method": "root", "timing": "При начале формирования головки", "fertilizer_type": "PK", "product_example": "Нитрофоска (NPK)"}]'::jsonb, diseases = '[{"name": "Кила", "symptoms": "Вздутия корней", "treatment": "Нет", "conditions": "Кислая почва", "prevention": "Известкование pH>7"}, {"name": "Чёрная ножка", "symptoms": "Потемнение стебля", "treatment": "Умеренный полив", "conditions": "Переувлажнение", "prevention": "Дренаж"}]'::jsonb, pests = '[{"name": "Капустная белянка", "signs": "Гусеницы", "treatment": "Лепидоцид", "prevention": "Укрывной материал"}, {"name": "Тля", "signs": "Колонии", "treatment": "Актеллик", "prevention": ""}]'::jsonb WHERE name = 'Капуста брокколи';
UPDATE crops SET watering_details = '{"notes": "Регулярный полив. Нельзя допускать пересыхания — уходит в стрелку.", "growing": {"freq_days": 2, "amount_l_m2": 6}}'::jsonb, fertilizing_schedule = '[{"dose": "10 г на 10 л", "notes": "", "stage": "growing", "method": "root", "timing": "Через 10 дней после появления всходов", "fertilizer_type": "N", "product_example": "Мочевина (азот, карбамид)"}]'::jsonb, diseases = '[{"name": "Слизистый бактериоз", "symptoms": "Слизистые загнивающие листья с запахом", "treatment": "Удалить повреждённые листья, Фитолавин", "conditions": "Жара + полив по листьям", "prevention": "Полив только под корень"}]'::jsonb, pests = '[{"name": "Крестоцветная блошка", "signs": "Дырки на листьях", "treatment": "Зола, Актеллик", "prevention": "Укрывной материал"}]'::jsonb WHERE name = 'Капуста пекинская';
UPDATE crops SET watering_details = '{"notes": "Влаголюбива, не переносит засухи. Мульчирование обязательно.", "growing": {"freq_days": 3, "amount_l_m2": 8}, "fruiting": {"freq_days": 2, "amount_l_m2": 12}}'::jsonb, fertilizing_schedule = '[{"dose": "15 г на 10 л", "notes": "", "stage": "seedling", "method": "root", "timing": "В фазе 3-4 листьев", "fertilizer_type": "NPK", "product_example": "Кемира (комплекс NPK)"}, {"dose": "15 г на 10 л", "notes": "", "stage": "growing", "method": "root", "timing": "Через 2 недели после высадки", "fertilizer_type": "N", "product_example": "Аммиачная селитра (азот)"}, {"dose": "20 г на 10 л", "notes": "+ внесение бора (2 г/10 л)", "stage": "fruiting", "method": "root", "timing": "При начале формирования головки", "fertilizer_type": "PK", "product_example": "Нитрофоска без хлора (NPK без хлора)"}]'::jsonb, diseases = '[{"name": "Кила", "symptoms": "Вздутия на корнях", "treatment": "Нет", "conditions": "Кислая почва", "prevention": "Известкование"}, {"name": "Пероноспороз", "symptoms": "Жёлтые пятна, серый налёт снизу", "treatment": "Ридомил Голд", "conditions": "Влажность", "prevention": "Проветривание"}]'::jsonb, pests = '[{"name": "Капустная белянка", "signs": "Гусеницы объедают листья", "treatment": "Лепидоцид, Битоксибациллин", "prevention": "Укрывной материал"}, {"name": "Крестоцветная блошка", "signs": "Мелкие дырки на листьях", "treatment": "Зола, Актеллик", "prevention": "Ранняя высадка"}]'::jsonb WHERE name = 'Капуста цветная';
UPDATE crops SET watering_details = '{"notes": "Полив в бутонизации и цветении — критически важен. 1 куст = 3-5 литров за раз. После цветения сокращаем. За 2 недели до уборки — прекращаем.", "growing": {"freq_days": 7, "amount_l_m2": 6}, "fruiting": {"freq_days": 5, "amount_l_m2": 8}, "flowering": {"freq_days": 4, "amount_l_m2": 10}}'::jsonb, fertilizing_schedule = '[{"dose": "20 г на 10 л", "notes": "Совместить с окучиванием", "stage": "growing", "method": "root", "timing": "При высоте ботвы 10-15 см", "fertilizer_type": "N", "product_example": "Нитроаммофоска (NPK)"}, {"dose": "20+20 г на 10 л", "notes": "Закладка клубней", "stage": "flowering", "method": "root", "timing": "В начале бутонизации", "fertilizer_type": "PK", "product_example": "Суперфосфат (фосфор) + сульфат калия (калий)"}, {"dose": "20 г на 10 л", "notes": "Налив клубней", "stage": "fruiting", "method": "root", "timing": "Через 2 недели после цветения", "fertilizer_type": "K", "product_example": "Сульфат калия (калий)"}]'::jsonb, diseases = '[{"name": "Фитофтороз", "symptoms": "Бурые пятна на листьях, белый налёт снизу, гниль клубней", "treatment": "Ридомил Голд, Ордан, бордоская смесь", "conditions": "Влажность >75%, перепад температур", "prevention": "Устойчивые сорта, опрыскивание с начала июля"}, {"name": "Парша обыкновенная", "symptoms": "Корковые трещины на клубнях", "treatment": "Нет", "conditions": "Щелочная почва, сухая погода", "prevention": "Кислая реакция почвы, севооборот"}, {"name": "Чёрная ножка", "symptoms": "Почернение стебля у основания, увядание куста", "treatment": "Убрать куст", "conditions": "Переувлажнение, заражённые клубни", "prevention": "Здоровый семенной материал, не переувлажнять"}]'::jsonb, pests = '[{"name": "Колорадский жук", "signs": "Оранжевые яйца под листьями, личинки объедают листья", "treatment": "Командор, Актара, Конфидор; биопрепарат Бовергрин", "prevention": "Мульчирование соломой, ручной сбор, посадка хрена по периметру"}, {"name": "Проволочник", "signs": "Ходы в клубнях", "treatment": "Базудин в лунку, Провотокс", "prevention": "Осенняя перекопка, горчица-сидерат"}]'::jsonb WHERE name = 'Картофель';
