UPDATE crops SET watering_details = '{"notes": "Поливать регулярно. Мульчирование удерживает влагу.", "growing": {"freq_days": 5, "amount_l_m2": 5}}'::jsonb, fertilizing_schedule = '[{"dose": "10 г на 10 л", "notes": "", "stage": "growing", "method": "root", "timing": "Ранней весной при отрастании", "fertilizer_type": "N", "product_example": "Аммиачная селитра (азот)"}]'::jsonb, diseases = '[]'::jsonb, pests = '[{"name": "Луковая муха", "signs": "Пожелтение пера", "treatment": "Базудин", "prevention": "Рядом с морковью"}]'::jsonb WHERE name = 'Лук-батун';
UPDATE crops SET watering_details = '{"notes": "Умеренный полив. Засухоустойчивее репчатого лука.", "growing": {"freq_days": 5, "amount_l_m2": 6}}'::jsonb, fertilizing_schedule = '[{"dose": "20 г на 10 л", "notes": "", "stage": "growing", "method": "root", "timing": "Через 3 недели после высадки", "fertilizer_type": "NPK", "product_example": "Кемира (комплекс NPK)"}, {"dose": "15 г на 10 л", "notes": "", "stage": "fruiting", "method": "root", "timing": "В августе", "fertilizer_type": "K", "product_example": "Сульфат калия (калий)"}]'::jsonb, diseases = '[{"name": "Пероноспороз", "symptoms": "Серый налёт на листьях", "treatment": "Ридомил Голд", "conditions": "Влажность", "prevention": "Проветривание"}]'::jsonb, pests = '[{"name": "Луковая муха", "signs": "Увядание пера", "treatment": "Базудин", "prevention": "Рядом с морковью"}]'::jsonb WHERE name = 'Лук-порей';
UPDATE crops SET watering_details = '{"notes": "В первую половину вегетации поливать умеренно. За месяц до уборки (середина июля) полив прекратить — луковицы лучше вызревают и хранятся.", "growing": {"freq_days": 5, "amount_l_m2": 5}, "fruiting": {"freq_days": 7, "amount_l_m2": 4}}'::jsonb, fertilizing_schedule = '[{"dose": "15 г на 10 л", "notes": "На перо — больше азота", "stage": "growing", "method": "root", "timing": "Через 2 недели после высадки", "fertilizer_type": "N", "product_example": "Аммиачная селитра (азот)"}, {"dose": "20 г на 10 л", "notes": "", "stage": "growing", "method": "root", "timing": "Через 3 недели после первой", "fertilizer_type": "NPK", "product_example": "Нитрофоска (NPK)"}, {"dose": "15+15 г на 10 л", "notes": "Азот исключить", "stage": "fruiting", "method": "root", "timing": "В начале формирования луковицы", "fertilizer_type": "PK", "product_example": "Суперфосфат (фосфор) + сульфат калия (калий)"}]'::jsonb, diseases = '[{"name": "Пероноспороз (ложная мучнистая роса)", "symptoms": "Серый налёт на листьях, листья желтеют и полегают", "treatment": "Ридомил Голд, Ордан", "conditions": "Влажная прохладная погода", "prevention": "Прогрев посевного материала (45°C 8 часов), широкие грядки"}, {"name": "Шейковая гниль", "symptoms": "Мягкая гниль у шейки луковицы при хранении", "treatment": "Нет, профилактика", "conditions": "Уборка при высокой влажности, недосушенный лук", "prevention": "Дать вызреть, хорошо просушить, хранить сухо"}]'::jsonb, pests = '[{"name": "Луковая муха", "signs": "Увядание и пожелтение пера, личинки в луковице", "treatment": "Базудин в почву, Актара", "prevention": "Лук рядом с морковью (взаимная защита), мульчирование"}, {"name": "Луковый скрытнохоботник", "signs": "Белые ходы в листьях, пожелтение", "treatment": "Актеллик при первых признаках", "prevention": "Ранний посев, осенняя перекопка"}]'::jsonb WHERE name = 'Лук репчатый';
UPDATE crops SET watering_details = '{"notes": "Полив у корня. В период созревания ягод — регулярный. Мульчирование обязательно.", "growing": {"freq_days": 7, "amount_l_m2": 8}, "fruiting": {"freq_days": 5, "amount_l_m2": 10}}'::jsonb, fertilizing_schedule = '[{"dose": "15 г на 1 м² (рассыпать)", "notes": "", "stage": "growing", "method": "root", "timing": "Ранней весной", "fertilizer_type": "N", "product_example": "Аммиачная селитра (азот)"}, {"dose": "По 20 г на 1 м²", "notes": "Закладка урожая следующего года", "stage": "fruiting", "method": "root", "timing": "После плодоношения", "fertilizer_type": "PK", "product_example": "Суперфосфат (фосфор)+сульфат калия (калий)"}]'::jsonb, diseases = '[{"name": "Антракноз", "symptoms": "Серые пятна с пурпурным ободком на побегах и листьях", "treatment": "Ридомил, бордоская смесь", "conditions": "Влажность", "prevention": "Прореживание, удаление больных побегов"}, {"name": "Дидимелла (пурпуровая пятнистость)", "symptoms": "Пурпурные пятна у основания побегов", "treatment": "ХОМ, бордоская смесь", "conditions": "Загущённые посадки", "prevention": "Нормировка побегов"}]'::jsonb, pests = '[{"name": "Малинный жук", "signs": "Личинки в ягодах", "treatment": "Актеллик, Карбофос до цветения", "prevention": "Рыхление почвы под кустами"}, {"name": "Малинно-земляничный долгоносик", "signs": "Опавшие бутоны", "treatment": "Актеллик до цветения", "prevention": "Осенняя уборка растительных остатков"}]'::jsonb WHERE name = 'Малина';
UPDATE crops SET watering_details = '{"notes": "Умеренный полив. Нельзя допускать пересыхания почвы — корнеплод трескается. Поверхностный полив вызывает ветвление. Поливать в борозды, не дождеванием.", "growing": {"freq_days": 5, "amount_l_m2": 5}, "fruiting": {"freq_days": 5, "amount_l_m2": 8}}'::jsonb, fertilizing_schedule = '[{"dose": "20 г на 1 м² (рассыпают и рыхлят)", "notes": "Азот умеренно", "stage": "growing", "method": "root", "timing": "В фазе 2-3 настоящих листьев", "fertilizer_type": "NPK", "product_example": "Нитрофоска (NPK)"}, {"dose": "15 г на 10 л", "notes": "Улучшает сахаристость, размер", "stage": "fruiting", "method": "root", "timing": "В июле, при активном росте корнеплода", "fertilizer_type": "K", "product_example": "Сульфат калия (калий)"}, {"dose": "1 стакан на 1 м² (поверхностно)", "notes": "Минеральный калий", "stage": "fruiting", "method": "root", "timing": "В августе", "fertilizer_type": "K", "product_example": "Зола"}]'::jsonb, diseases = '[{"name": "Фомоз (сухая гниль)", "symptoms": "Серовато-коричневые пятна на корнеплодах, белый налёт при хранении", "treatment": "Обработка корнеплодов перед хранением", "conditions": "Недостаток бора, влажность при хранении", "prevention": "Внесение буры 2-4 г/м², правильное хранение"}, {"name": "Чёрная гниль (альтернариоз)", "symptoms": "Чёрные вдавленные пятна на корнеплодах", "treatment": "Нет, профилактика", "conditions": "Поражение в поле, распространяется при хранении", "prevention": "Севооборот, обеззараживание семян, не травмировать при уборке"}]'::jsonb, pests = '[{"name": "Морковная муха", "signs": "Красновато-фиолетовые листья, ходы и гниль в корнеплоде", "treatment": "Защитные укрытия (агроволокно), Базудин в почву", "prevention": "Посев лука и чеснока рядом — запах отпугивает"}, {"name": "Морковная листоблошка", "signs": "Скручивание листьев, деформация корнеплода", "treatment": "Актара, Актеллик", "prevention": "Укрывной материал, уничтожение хвойного подлеска рядом"}]'::jsonb WHERE name = 'Морковь';
UPDATE crops SET watering_details = '{"notes": "Любит влагу. Не переносит засуху.", "growing": {"freq_days": 3, "amount_l_m2": 4}}'::jsonb, fertilizing_schedule = '[{"dose": "5 г на 10 л", "notes": "Слабый раствор", "stage": "growing", "method": "root", "timing": "Весной при отрастании", "fertilizer_type": "N", "product_example": "Мочевина (азот, карбамид)"}]'::jsonb, diseases = '[{"name": "Ржавчина", "symptoms": "Оранжевые пятна на листьях", "treatment": "Медьсодержащие препараты", "conditions": "Влажность", "prevention": "Хорошая вентиляция"}]'::jsonb, pests = '[{"name": "Паутинный клещ", "signs": "Паутина на листьях", "treatment": "Фитоверм", "prevention": "Полив листьев"}]'::jsonb WHERE name = 'Мята';
UPDATE crops SET watering_details = '{"notes": "Поливать только тёплой водой (20-25°C). Холодный полив вызывает прикорневую гниль. Лучше ежедневно небольшими порциями. Мульчирование обязательно.", "growing": {"freq_days": 2, "amount_l_m2": 6}, "fruiting": {"freq_days": 1, "amount_l_m2": 10}, "seedling": {"freq_days": 2, "amount_l_m2": 4}, "flowering": {"freq_days": 1, "amount_l_m2": 8}}'::jsonb, fertilizing_schedule = '[{"dose": "10 г на 10 л", "notes": "Активный рост листьев и стеблей", "stage": "growing", "method": "root", "timing": "Через 2 недели после высадки", "fertilizer_type": "N", "product_example": "Мочевина (азот, карбамид)"}, {"dose": "15 г на 10 л", "notes": "Сбалансированная подкормка", "stage": "flowering", "method": "root", "timing": "В начале цветения", "fertilizer_type": "NPK", "product_example": "Нитроаммофоска (NPK)"}, {"dose": "20 г на 10 л", "notes": "Продлевает плодоношение, предотвращает горечь", "stage": "fruiting", "method": "root", "timing": "Каждые 10-12 дней", "fertilizer_type": "K", "product_example": "Калимагнезия (калий + магний)"}]'::jsonb, diseases = '[{"name": "Мучнистая роса", "symptoms": "Белый мучнистый налёт на листьях, постепенно лист желтеет и засыхает", "treatment": "Коллоидная сера, Топаз, Квадрис, раствор соды (5 г + 5 г мыла на 1 л)", "conditions": "Перепады температур, высокая влажность, сухая почва при влажном воздухе", "prevention": "Проветривание, избегать резких перепадов температур"}, {"name": "Пероноспороз (ложная мучнистая роса)", "symptoms": "Угловатые жёлто-зелёные пятна на верхней стороне листьев, серо-фиолетовый налёт снизу", "treatment": "Ридомил Голд, Ордан, бордоская смесь", "conditions": "Влажность >80%, температура 12-18°C, обильные росы", "prevention": "Полив только под корень, проветривание, устойчивые сорта"}, {"name": "Корневая гниль", "symptoms": "Пожелтение нижних листьев, потемнение основания стебля, увядание в жару", "treatment": "Превикур Энерджи, Триходерма вериде (биопрепарат)", "conditions": "Холодный полив, переувлажнение, кислая почва", "prevention": "Тёплая вода для полива, рыхление, посыпать основание золой"}, {"name": "Угловатая пятнистость (бактериоз)", "symptoms": "Угловатые мокрые пятна на листьях, ограниченные жилками, подсыхают и выпадают", "treatment": "ХОМ, бордоская смесь, Фитолавин", "conditions": "Дождливая погода, механические повреждения", "prevention": "Обеззараживание семян, профилактические опрыскивания"}]'::jsonb, pests = '[{"name": "Паутинный клещ", "signs": "Мелкие точки на листьях, тонкая паутина, листья бледнеют и засыхают", "treatment": "Фитоверм, Акарин, Клещевит; опрыскивание водой (клещ не любит влагу)", "prevention": "Поддерживать влажность воздуха >70%, опрыскивать листья снизу"}, {"name": "Бахчевая тля", "signs": "Колонии под листьями и на молодых побегах, скручивание верхушек", "treatment": "Актара, Биотлин, мыльный раствор, зольный настой", "prevention": "Своевременное уничтожение сорняков, бархатцы рядом"}, {"name": "Белокрылка", "signs": "Белые мошки, липкий налёт, пожелтение листьев", "treatment": "Актара, Конфидор, жёлтые клеевые ловушки", "prevention": "Проветривание, поддержание умеренной температуры"}]'::jsonb WHERE name = 'Огурец';
