UPDATE crops SET watering_details = '{"notes": "Перец очень чувствителен к холодной воде — только тёплая (25°C). Не переливать: корни загнивают. Умеренный, равномерный полив.", "growing": {"freq_days": 3, "amount_l_m2": 5}, "fruiting": {"freq_days": 2, "amount_l_m2": 8}, "seedling": {"freq_days": 4, "amount_l_m2": 2}, "flowering": {"freq_days": 2, "amount_l_m2": 7}}'::jsonb, fertilizing_schedule = '[{"dose": "5 г на 5 л", "notes": "Слабый раствор", "stage": "seedling", "method": "root", "timing": "Через 2 недели после пикировки", "fertilizer_type": "NPK", "product_example": "Агрикола (комплекс NPK) для томатов и перцев"}, {"dose": "15 г на 10 л", "notes": "Стимуляция роста", "stage": "growing", "method": "root", "timing": "Через 2 недели после высадки", "fertilizer_type": "N", "product_example": "Нитроаммофоска (NPK)"}, {"dose": "15 г на 10 л", "notes": "Внекорневая подкормка по листьям утром", "stage": "flowering", "method": "foliar", "timing": "При появлении бутонов", "fertilizer_type": "PK", "product_example": "Монофосфат калия (фосфор + калий)"}, {"dose": "20 г на 10 л", "notes": "Поддержание плодоношения", "stage": "fruiting", "method": "root", "timing": "Каждые 2 недели", "fertilizer_type": "K", "product_example": "Сульфат калия (калий)"}]'::jsonb, diseases = '[{"name": "Фитофтороз", "symptoms": "Бурые пятна на листьях и плодах, белый налёт при влажности", "treatment": "Ридомил Голд, Превикур, бордоская смесь", "conditions": "Высокая влажность, холодные ночи", "prevention": "Проветривание, мульчирование"}, {"name": "Вершинная гниль", "symptoms": "Тёмные пятна у вершины плода", "treatment": "Кальциевая селитра 0,4% опрыскивание", "conditions": "Дефицит кальция, нерегулярный полив", "prevention": "Равномерный полив, мульчирование"}, {"name": "Серая гниль", "symptoms": "Серый пушистый налёт на стеблях и плодах", "treatment": "Свитч, Фундазол", "conditions": "Высокая влажность, загущённые посадки", "prevention": "Прореживание, удаление нижних листьев"}]'::jsonb, p