UPDATE crops SET watering_details = '{"notes": "Поливать тёплой водой 18-20°C строго под корень. Избегать попадания на листья. Не допускать пересыхания в период налива плодов.", "growing": {"freq_days": 3, "amount_l_m2": 6}, "fruiting": {"freq_days": 2, "amount_l_m2": 10}, "seedling": {"freq_days": 4, "amount_l_m2": 3}, "sprouted": {"freq_days": 3, "amount_l_m2": 4}, "flowering": {"freq_days": 2, "amount_l_m2": 8}}'::jsonb, fertilizing_schedule = '[{"dose": "10 г на 10 л воды", "notes": "После появления 2-3 настоящих листьев", "stage": "seedling", "method": "root", "timing": "Через 10-14 дней после появления всходов", "fertilizer_type": "N", "product_example": "Нитрофоска (NPK)"}, {"dose": "20 г на 10 л", "notes": "Стимулирует наращивание корневой системы", "stage": "growing", "method": "root", "timing": "Через 2 недели после высадки в грунт", "fertilizer_type": "NPK", "product_example": "Кемира Универсал (комплекс NPK + микроэлементы)"}, {"dose": "15 г на 10 л", "notes": "Азот резко снижаем, упор на фосфор и калий", "stage": "flowering", "method": "root", "timing": "При появлении первых цветочных кистей", "fertilizer_type": "PK", "product_example": "Монофосфат калия (фосфор + калий)"}, {"dose": "20 г на 10 л", "notes": "Улучшает вкус и лёжкость плодов", "stage": "fruiting", "method": "root", "timing": "Каждые 10-14 дней", "fertilizer_type": "K", "product_example": "Сульфат калия (калий)"}]'::jsonb, diseases = '[{"name": "Фитофтороз", "symptoms": "Бурые маслянистые пятна на листьях и плодах, белый налёт на нижней стороне листа в сырую погоду", "treatment": "Ридомил Голд, Превикур Энерджи, бордоская смесь 1%", "conditions": "Влажность >75%, перепады температур 10-15°C", "prevention": "Проветривание теплицы, мульчирование, не поливать по листьям"}, {"name": "Кладоспориоз (бурая пятнистость)", "symptoms": "Светло-жёлтые пятна на верхней стороне листьев, бархатистый оливково-серый налёт снизу", "treatment": "ХОМ, Полихом, Квадрис, бордоская смесь", "conditions": "Влажно