 листья, чёрные слизистые личинки", "treatment": "Инта-Вир при обнаружении", "prevention": "Осенняя перекопка приствольных кругов"}]'::jsonb WHERE name = 'Черешня';
UPDATE crops SET watering_details = '{"notes": "Озимый: поливать весной при отрастании. За 3 недели до уборки полив прекратить. Яровой: полив умеренный весь период. Переувлажнение вызывает гниль.", "growing": {"freq_days": 5, "amount_l_m2": 5}, "fruiting": {"freq_days": 7, "amount_l_m2": 4}}'::jsonb, fertilizing_schedule = '[{"dose": "10 г на 10 л", "notes": "Озимый чеснок — первая подкормка", "stage": "growing", "method": "root", "timing": "Ранней весной при отрастании", "fertilizer_type": "N", "product_example": "Аммиачная селитра (азот)"}, {"dose": "15 г на 10 л", "notes": "", "stage": "growing", "method": "root", "timing": "В мае, в фазе 5-6 листьев", "fertilizer_type": "NPK", "product_example": "Нитроаммофоска (NPK)"}, {"dose": "15 г на 10 л", "notes": "Формирование головки", "stage": "fruiting", "method": "root", "timing": "В начале июня", "fertilizer_type": "PK", "product_example": "Монофосфат калия (фосфор + калий)"}]'::jsonb, diseases = '[{"name": "Фузариоз (гниль донца)", "symptoms": "Пожелтение листьев, гниль в основании луковицы, белый налёт", "treatment": "Превикур", "conditions": "Высокая температура, влажная почва", "prevention": "Обеззараживание зубков марганцовкой перед посадкой, севооборот"}, {"name": "Белая гниль", "symptoms": "Белый ватообразный налёт у основания, полегание", "treatment": "Нет лечения", "conditions": "Прохлада, сырость", "prevention": "Дренированная почва, севооборот 4-5 лет"}]'::jsonb, pests = '[{"name": "Луковая муха", "signs": "Пожелтение пера, личинки в основании", "treatment": "Базудин в почву, полив солевым раствором (250 г/10 л)", "prevention": "Мульчирование, рядом с морковью"}, {"name": "Стеблевая нематода", "signs": "Деформация луковицы, серебристость чешуй", "treatment": "Нет эффективного лечения", "prevention": "Обеззараживание зубков горячей водой 45°C 15 мин, севооборот"}]'::jsonb WHERE name = 'Чеснок';
UPDATE crops SET watering_details = '{"notes": "Регулярный полив. При засухе горчит и стрелкует. Любит прохладу.", "growing": {"freq_days": 2, "amount_l_m2": 5}}'::jsonb, fertilizing_schedule = '[{"dose": "5 г на 10 л", "notes": "Слабый раствор", "stage": "growing", "method": "root", "timing": "Через 2 недели после всходов", "fertilizer_type": "N", "product_example": "Аммиачная селитра (азот)"}]'::jsonb, diseases = '[{"name": "Пероноспороз", "symptoms": "Жёлтые пятна, серо-фиолетовый налёт снизу", "treatment": "Ридомил", "conditions": "Влажность", "prevention": "Прореживание"}]'::jsonb, pests = '[{"name": "Тля", "signs": "Колонии на листьях", "treatment": "Мыльный раствор", "prevention": ""}]'::jsonb WHERE name = 'Шпинат';
UPDATE crops SET watering_details = '{"notes": "Любит влагу. При засухе листья грубеют и кислят сильнее.", "growing": {"freq_days": 5, "amount_l_m2": 6}}'::jsonb, fertilizing_schedule = '[{"dose": "10 г на 10 л", "notes": "После каждой срезки", "stage": "growing", "method": "root", "timing": "Ранней весной", "fertilizer_type": "N", "product_example": "Мочевина (азот, карбамид)"}]'::jsonb, diseases = '[{"name": "Ложная мучнистая роса", "symptoms": "Жёлтые пятна, налёт", "treatment": "Ридомил", "conditions": "Влажность", "prevention": "Прореживание"}]'::jsonb, pests = '[{"name": "Щавелевый листоед", "signs": "Дырки в листьях", "treatment": "Актеллик", "prevention": ""}]'::jsonb WHERE name = 'Щавель';
UPDATE crops SET watering_details = '{"notes": "Взрослая яблоня: 4–5 поливов за сезон по 40–60 л под дерево. Особенно важны: через 2–3 недели после цветения, за 2–3 недели до сбора плодов и после листопада. Не поливать в период налива и при дождях.", "growing": {"freq_days": 21, "amount_l_m2": 30}, "fruiting": {"freq_days": 14, "amount_l_m2": 40}}'::jsonb, fertilizing_schedule = '[{"dose": "30 г на 1 м² приствольного круга", "notes": "Рассыпать и заделать в почву", "stage": "growing", "method": "root", "timing": "Ранней весной при распускании листьев", "fertilizer_type": "N", "product_example": "Аммиачная селитра"}, {"dose": "50 г на 10 л под дерево", "notes": "Стимуляция завязеобразования", "stage": "flowering", "method": "root", "timing": "Через 2 недели после цветения", "fertilizer_type": "NPK", "product_example": "Нитрофоска"}, {"dose": "20 г на 10 л", "notes": "Улучшение вкуса и лёжкости", "stage": "fruiting", "method": "root", "timing": "Июль — налив плодов", "fertilizer_type": "K", "product_example": "Сульфат калия"}, {"dose": "40 г на 1 м² + зола 0,5 кг", "notes": "Осенняя заправка почвы под перекопку", "stage": "done", "method": "root", "timing": "После листопада (сентябрь-октябрь)", "fertilizer_type": "P", "product_example": "Суперфосфат"}]'::jsonb, diseases = '[{"name": "Парша яблони", "symptoms": "Оливково-бурые пятна на листьях и плодах, трещины в коре плодов", "treatment": "Скор, Хорус (до цветения), Раёк; повторно после цветения", "conditions": "Влажная холодная весна, загущённые посадки", "prevention": "Устойчивые сорта, уборка листвы, обрезка для проветривания"}, {"name": "Монилиоз (плодовая гниль)", "symptoms": "Бурые гниющие пятна на плодах, кольца серых подушечек", "treatment": "Хорус, Свитч при первых признаках", "conditions": "Влажное лето, повреждения кожицы (парша, червоточины)", "prevention": "Удаление и уничтожение больных плодов, обработка Хорусом"}, {"name": "Мучнистая роса", "symptoms": "Белый налёт на молодых листьях и побегах весной", "treatment": "Скор, Топаз, сера коллоидная", "conditions": "Сухость после дождей, уязвимы молодые приросты", "prevention": "Обрезка поражённых побегов до здоровой ткани"}]'::jsonb, pests = '[{"name": "Яблонный цветоед", "signs": "Бутоны засыхают не раскрываясь («загнившие шапочки»), внутри личинка", "treatment": "Искра, Кинмикс, Децис при набухании почек", "prevention": "Стряхивание жуков ранним утром на плёнку при +7-8°C"}, {"name": "Яблонная плодожорка", "signs": "Червивые плоды с ходами к семенной камере, преждевременное опадение плодов", "treatment": "Хлорофос, Искра, Кинмикс через 2 недели после цветения; повтор через 14 дней", "prevention": "Ловчие пояса на стволах, уборка падалицы"}, {"name": "Тля зелёная яблонная", "signs": "Скрученные молодые листья на кончиках побегов, липкий налёт", "treatment": "Фитоверм, Актара, Биотлин при первых колониях", "prevention": "Привлечение полезных насекомых: укроп, петрушка рядом"}]'::jsonb WHERE name = 'Яблоня';

-- ---- ПЕТУНИЯ (единственная культура без агрономии — написано вручную 2026-07-30) ----
-- Однолетник в кашпо/на клумбе. Стадии `fruiting` у неё нет по смыслу: урожая не бывает,
-- цветение и есть «полезная» стадия, поэтому подкормки заканчиваются на flowering.
UPDATE crops SET
  watering_details = '{
    "seedling":  {"freq_days":2,"amount_l_m2":2},
    "growing":   {"freq_days":2,"amount_l_m2":4},
    "flowering": {"freq_days":1,"amount_l_m2":6},
    "notes": "Поливать под корень, не по цветкам: от воды лепестки закисают и буреют. В кашпо земля пересыхает быстрее, чем на клумбе — в жару нужен полив утром и вечером."
  }'::jsonb,
  fertilizing_schedule = '[
    {"stage":"seedling","timing":"Через 2 недели после пикировки","fertilizer_type":"NPK","product_example":"Кемира (комплекс NPK)","dose":"5 г на 10 л","method":"root","notes":"Половинная доза — рассада легко горит"},
    {"stage":"growing","timing":"Каждые 2 недели до бутонизации","fertilizer_type":"N","product_example":"Мочевина (азот, карбамид)","dose":"10 г на 10 л","method":"root","notes":"Наращивает куст; после появления бутонов азот убирать"},
    {"stage":"flowering","timing":"Каждые 7-10 дней всё цветение","fertilizer_type":"PK","product_example":"Монофосфат калия (фосфор + калий)","dose":"15 г на 10 л","method":"root","notes":"Без регулярной подкормки цветение мельчает уже к июлю"}
  ]'::jsonb,
  diseases = '[
    {"name":"Чёрная ножка","symptoms":"Стебель у земли темнеет и истончается, сеянец падает","conditions":"Загущённый посев, переувлажнение, холодная почва","treatment":"Убрать поражённые сеянцы, пролить Фитоспорином, подсушить грунт","prevention":"Редкий посев, лёгкий грунт, полив умеренный"},
    {"name":"Мучнистая роса","symptoms":"Белый мучнистый налёт на листьях и бутонах","conditions":"Резкие перепады температуры, загущение, избыток азота","treatment":"Топаз, Скор, коллоидная сера","prevention":"Прореживание побегов, проветривание, не заливать"},
    {"name":"Серая гниль","symptoms":"Бурые мокнущие пятна, пушистый серый налёт на побегах и цветках","conditions":"Сырая прохладная погода, плотная посадка","treatment":"Удалить поражённые части, обработать Свитчем или Фундазолом","prevention":"Убирать отцветшие венчики, не поливать по кусту"}
  ]'::jsonb,
  pests = '[
    {"name":"Тля","signs":"Липкие скрученные верхушки, колонии мелких насекомых на бутонах","treatment":"Фитоверм, Актара, мыльный раствор","prevention":"Осмотр верхушек раз в неделю, не перекармливать азотом"},
    {"name":"Паутинный клещ","signs":"Мелкие светлые точки на листьях, тонкая паутина в пазухах","treatment":"Фитоверм, Клещевит; опрыскивание водой по листу","prevention":"Влажность воздуха; в жару опрыскивать вечером"},
    {"name":"Белокрылка","signs":"Белые мошки взлетают при касании куста, липкий налёт на листьях","treatment":"Актара, Конфидор; жёлтые клеевые ловушки","prevention":"Ловушки с начала сезона, осмотр нижней стороны листьев"},
    {"name":"Трипс","signs":"Серебристые штрихи на лепестках, деформированные бутоны","treatment":"Актара, Спинтор","prevention":"Удалять сорняки рядом, синие клеевые ловушки"}
  ]'::jsonb
WHERE name = 'Петуния';
